#include <stdio.h>
#include <stdlib.h>

struct node { char c; struct node* next; };

struct node* build(char* s) {
    struct node *head = NULL, *tail = NULL;
    while (*s) {
        struct node* n = malloc(sizeof(struct node));
        n->c = *s++;
        n->next = NULL;
        if (head == NULL) head = tail = n;
        else { tail->next = n; tail = n; }
    }
    return head;
}

void printReverse(struct node* n) {
    if (n == NULL) return;
    printReverse(n->next);
    putchar(n->c);
}

int main() {
    struct node* head = build("LINK");
    printReverse(head);
    return 0;
}

#include <stdio.h>

int isArmstrong(int n) {
    int digits = 0, temp = n, sum = 0;
    while (temp > 0) { digits++; temp /= 10; }
    temp = n;
    while (temp > 0) {
        int d = temp % 10;
        int p = 1;
        for (int i = 0; i < digits; i++) p *= d;
        sum += p;
        temp /= 10;
    }
    return sum == n;
}

int main(){
    int sum = 0;
    for (int i = 100; i <= 500; i++){
        if (isArmstrong(i))
            sum += i;
    }
    printf("%d", sum);
    return 0;
}

